head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
scwin.onpageload = function() {
	var data1 = [];
	var data2 = [];
	var data3 = [];
	var row = 10;
	var col = 3;
	for (var i = 0; i < row; i++) {
		for (var j = 0; j < col; j++) {
			if (j === 0) {
				data1.push("label=" + String(i));
				data2.push("L=" + String(i));
				data3.push("_L_:" + String(i));
			} else if (j === 1) {
				data1.push("value=" + String(i));
				data2.push("V=" + String(i));
				data3.push("_V_:" + String(i));
			} else {
				data1.push("dummy=" + String(i));
				data2.push("D=" + String(i));
				data3.push("_d_:" + String(i));
			}
		}
	}
	dataList1.setData(data1);
	dataList2.setData(data2);
	dataList3.setData(data3);
	dataList4.insertRow();
};
scwin.trigger1_onclick = function(e) {
	var obj = {
		"nodeset": "data:dataList2",
		"label": "label",
		"value": "value",
		"width": 1000,
		"height": 800,
		"visibleRowNum": 10,
		"item": [{
			"ref": "label",
			"header": "NLabel"
		}, {
			"ref": "value",
			"header": "NValue"
		}, {
			"ref": "col3",
			"header": "NDummy"
		}]
	};
	selectbox1.setGridItemset(obj);
};
scwin.trigger2_onclick = function(e) {
	var obj = {
		"nodeset": "data:dataList3",
		"label": "label",
		"value": "value",
		"width": 1000,
		"height": 1300,
		"visibleRowNum": 10,
		"item": [{
			"ref": "label",
			"header": "NLabel"
		}, {
			"ref": "value",
			"header": "NValue"
		}, {
			"ref": "col3",
			"header": "NDummy"
		}]
	};
	autoComplete1.setGridItemset(obj);
};
scwin.trigger4_onclick = function(e) {
	var obj1 = {
		"nodeset": "data:dataList2",
		"label": "label",
		"value": "value",
		"width": 600,
		"height": 300,
		"visibleRowNum": 10,
		"item": [{
			"ref": "label",
			"header": "NLabel"
		}, {
			"ref": "value",
			"header": "NValue"
		}, {
			"ref": "col3",
			"header": "NDummy"
		}]
	};
	gridView1.setColumnGridItemset(0, obj1);
};
	scwin.dbClick = function(id) {
		var el = scwin.__getDom(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}
scwin.checkVal = function() {
	return parseInt(scwin.__getDom('G_'+$p.id+'gridView1___selectbox_col1_gridViewItemTable_gridView').offsetWidth) > parseInt(parseInt((document.getElementById('gridView1_head_table') || document.getElementById('mf_gridView1_head_table')).style.width))
}
